// Both imports are generated by `npm run cf:build` from the installed yoga-layout.
import yogaModule from './yoga.wasm'
import yogaWasm from './yoga-wasm.json'
import { redirectInstantiateToPrecompiled } from './yoga-redirect'

redirectInstantiateToPrecompiled(WebAssembly, {
  module: yogaModule,
  byteLength: yogaWasm.byteLength,
  sha256: yogaWasm.sha256,
})
